fn is_palindrome(text: Vec<char>) -> bool {
    let n = text.len();
    for i in 0..n / 2 {
        let left = text[i];
        let right = text[n - 1 - i];
        
        // ASCII case-insensitive comparison
        if left.to_ascii_lowercase() != right.to_ascii_lowercase() {
            return false;
        }
    }
    true
}